using UnityEngine;using UnityEngine.AI;using System.Collections;using System.IO;
public class HunterCompatibilityProbe:MonoBehaviour{
 IEnumerator Start(){string dir=Path.GetFullPath("Evidence/hunter-gameplay-validation");Directory.CreateDirectory(dir);string log=dir+"/results.txt";File.WriteAllText(log,"Unity "+Application.unityVersion+" platform="+Application.platform+"\nDirect API behavior probe; not keyboard simulation.\n");var p=GetComponent<DemoMovement>();var a=GetComponent<NavMeshAgent>();var bridge=GetComponent<HunterGameplayAnimator>();
 yield return new WaitForSeconds(.5f);File.AppendAllText(log,"onNavMesh="+a.isOnNavMesh+" human="+bridge.animator.isHuman+" rootMotion="+bridge.animator.applyRootMotion+"\n");Vector3 start=transform.position;if(a.isOnNavMesh)a.SetDestination(start+Vector3.forward*2);yield return new WaitForSeconds(.35f);ScreenCapture.CaptureScreenshot(dir+"/moving.png");yield return new WaitForSeconds(.8f);File.AppendAllText(log,"movementState="+bridge.animator.GetCurrentAnimatorStateInfo(0).shortNameHash+" movementDistance="+Vector3.Distance(start,transform.position)+"\n");p.TakeManualControl();start=transform.position;bool dodged=p.TryDodge(Vector3.right);yield return new WaitForSeconds(.1f);File.AppendAllText(log,"dodgeState="+bridge.animator.GetCurrentAnimatorStateInfo(0).shortNameHash+"\n");ScreenCapture.CaptureScreenshot(dir+"/dodge.png");yield return new WaitForSeconds(.35f);File.AppendAllText(log,"dodgeAccepted="+dodged+" distance="+Vector3.Distance(start,transform.position)+"\n");
 var enemy=FindObjectOfType<DemoEnemy>();if(enemy){var ea=enemy.GetComponent<NavMeshAgent>();ea.Warp(transform.position+Vector3.forward*1.4f);p.SelectEnemy(enemy);yield return new WaitForSeconds(.12f);File.AppendAllText(log,"attackState="+bridge.animator.GetCurrentAnimatorStateInfo(0).shortNameHash+"\n");ScreenCapture.CaptureScreenshot(dir+"/attack.png");File.AppendAllText(log,"attackMessage="+p.message+" targetAlive="+enemy.IsAlive+"\n");}
 File.AppendAllText(log,"Probe complete; animation action clips must be separately checked.\n");}
}
